// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));

        address origOwner = c.owner();

        vm.prank(caller);
        bool ok;
        try c.setOwner(caller) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        assertTrue(c.owner() == origOwner);
    }
}
